             && (task.highlighted || model.IsActive === true)
    x: frame.x + frame.width - frame.fixedMargins.right
    y: frame.y + frame.fixedMargins.top + 4
    width: 3
    height: Math.max(0, frame.height - frame.fixedMargins.top - frame.fixedMargins.bottom - 8)
    clip: true
    Rectangle {
        readonly property bool dark: Kirigami.ColorUtils.brightnessForColor(Kirigami.Theme.backgroundColor) === Kirigami.ColorUtils.Dark
        anchors.right: parent.right
        width: 14
        height: parent.height
        radius: 4
        color: dark ? Qt.alpha(Kirigami.Theme.textColor, 0.09) : Qt.rgba(1, 1, 1, 0.42)
        border.width: 1
        border.color: dark ? Qt.rgba(1, 1, 1, 0.07) : Qt.rgba(0, 0, 0, 0.09)
    }
}

